import org.junit.jupiter.api.Test;

/**
 * A detached refresh replans the prepared source, which already embeds the request-bound rewrites. It may therefore
 * only execute while the assumptions those rewrites made still hold; otherwise it must fail before opening a planning
 * snapshot so the family is replaced by a synchronous replan from the unrewritten query.
 */
class LmdbDetachedPlanRefreshAssumptionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");

	@Test
	void committedSnapshotDependentRefreshRefusesToRunAtAnotherDataRevision() {
		LmdbEstimatorRuntime runtime = runtime(18L);
		AtomicInteger snapshotsOpened = new AtomicInteger();
		LmdbDetachedPlanRefresh refresh = refresh(runtime, snapshotsOpened, new LmdbPlanAssumptions(true, Set.of()),
				identity(RdfTermDomain.UNRESTRICTED), 17L);

		IllegalStateException failure = assertThrows(IllegalStateException.class, refresh::execute);

		assertTrue(failure.getMessage().contains("committed-snapshot"), failure.getMessage());
		assertEquals(0, snapshotsOpened.get(), "stale assumptions must fail before any planning snapshot opens");
	}

	@Test
	void guaranteeDependentRefreshRefusesToRunWhenTheGuaranteeChanged() {
		LmdbEstimatorRuntime runtime = runtime(18L);
		AtomicInteger snapshotsOpened = new AtomicInteger();
		// The runtime under test serves UNRESTRICTED for every predicate; the plan was built while :p was guaranteed
		// canonical-integer, so the consumed guarantee no longer holds.
		LmdbDetachedPlanRefresh refresh = refresh(runtime, snapshotsOpened, new LmdbPlanAssumptions(false, Set.of(P)),
				identity(RdfTermDomain.CANONICAL_INTEGER), 18L);

		IllegalStateException failure = assertThrows(IllegalStateException.class, refresh::execute);

		assertTrue(failure.getMessage().contains("predicate-guarantee"), failure.getMessage());
		assertEquals(0, snapshotsOpened.get());
	}

	@Test
	void guaranteeDependentRefreshWithUnchangedGuaranteeReachesThePlanningSnapshot() {
		LmdbEstimatorRuntime runtime = runtime(18L);
		AtomicInteger snapshotsOpened = new AtomicInteger();
		LmdbDetachedPlanRefresh refresh = refresh(runtime, snapshotsOpened, new LmdbPlanAssumptions(false, Set.of(P)),
				identity(RdfTermDomain.UNRESTRICTED), 17L);

		SnapshotRequested reached = assertThrows(SnapshotRequested.class, refresh::execute);

		assertEquals(1, snapshotsOpened.get(), reached.getMessage());
	}

	@Test
	void refreshWithoutAssumptionsIgnoresTheDataRevision() {
		LmdbEstimatorRuntime runtime = runtime(18L);
		AtomicInteger snapshotsOpened = new AtomicInteger();
		LmdbDetachedPlanRefresh refresh = refresh(runtime, snapshotsOpened, LmdbPlanAssumptions.NONE,
				identity(RdfTermDomain.CANONICAL_INTEGER), 17L);

		assertThrows(SnapshotRequested.class, refresh::execute);

		assertEquals(1, snapshotsOpened.get(), "a data-independent refresh proceeds at any data revision");
	}

	private static LmdbEstimatorRuntime runtime(long dataRevision) {
		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.getDataRevision()).thenReturn(dataRevision);
		when(tripleStore.effectiveRdfTermDomainsVersion()).thenReturn("test-guarantee-schema");
		return new LmdbEstimatorRuntime(null, tripleStore, null, null, null, null, null);
	}

	private static LmdbDetachedPlanRefresh refresh(LmdbEstimatorRuntime runtime, AtomicInteger snapshotsOpened,
			LmdbPlanAssumptions assumptions, LmdbPipelinePlanCache.PredicateRangeIdentity buildRangeIdentity,
			long buildDataRevision) {
		LmdbDetachedPlanningSnapshotProvider snapshots = () -> {
			snapshotsOpened.incrementAndGet();
			throw new SnapshotRequested();
		};
		return new LmdbDetachedPlanRefresh(runtime, snapshots, work(), LmdbPipelinePlanCache.DatasetIdentity.of(null),
				LmdbPipelinePlanCache.BindingIdentity.of(null), false, false, false, QueryEvaluationMode.STANDARD,
				LmdbCascadesOptimizer.Mode.AUTO, runtime.predicateRangeVersion(), buildRangeIdentity, true,
				assumptions, buildDataRevision);
	}

	private static LmdbPipelinePlanCache.PredicateRangeIdentity identity(RdfTermDomain domain) {
		return new LmdbPipelinePlanCache.PredicateRangeIdentity(
				List.of(new LmdbPipelinePlanCache.PredicateRangeEntry(P, domain)));
	}

	private static PackedPlanRefreshWork work() {
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("o"));
		QueryRoot source = new QueryRoot(new Projection(pattern, new ProjectionElemList(new ProjectionElem("s"))));
		return PackedCascadesPlanner.detachedRefreshWork(source, null,
				LmdbPipelinePlanCacheAssumptionTest.decisionSummary(Set.of())).orElseThrow();
	}

	/** Marker thrown by the snapshot provider: the refresh passed its assumption checks and asked for a snapshot. */
	private static final class SnapshotRequested extends RuntimeException {

		private static final long serialVersionUID = 1L;

		private SnapshotRequested() {
			super("planning snapshot requested");
		}
	}
}
